        "code": "from collections import OrderedDict\nfrom dataclasses import dataclass\nfrom typing import Dict, List\n\n@dataclass\nclass Order:\n    order_id: int\n    side: str  # 'BUY' or 'SELL'\n    price: float\n    qty: int\n\nclass SimpleOrderBook:\n    def __init__(self):\n        self.bids: Dict[float, OrderedDict] = {} # price -> {order_id: Order}\n        self.asks: Dict[float, OrderedDict] = {}\n        \n    def add_limit_order(self, order: Order):\n        book = self.bids if order.side == 'BUY' else self.asks\n        if order.price not in book:\n            book[order.price] = OrderedDict()\n        book[order.price][order.order_id] = order\n        \n    def best_bid_ask(self):\n        bb = max(self.bids.keys()) if self.bids else None\n        ba = min(self.asks.keys()) if self.asks else None\n        return bb, ba\n\n# 单元断言测试\nob = SimpleOrderBook()\nob.add_limit_order(Order(1, 'BUY', 100.0, 50))\nob.add_limit_order(Order(2, 'BUY', 100.5, 30))\nob.add_limit_order(Order(3, 'SELL', 101.0, 100))\nbb, ba = ob.best_bid_ask()\nassert bb == 100.5 and ba == 101.0\nprint(f\"[PASS] 订单簿初始化成功! Best Bid: {bb}, Best Ask: {ba}\")",
